content:
* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
  font-family: system-ui, -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Oxygen, Ubuntu, Cantarell, 'Open Sans', 'Helvetica Neue', sans-serif;
}

body {
  background-color: #f3f4f6;
  color: #1f2937;
  display: flex;
  justify-content: center;
  align-items: center;
  min-height: 100vh;
  padding: 1rem;
}

.app-container {
  width: 100%;
  max-width: 500px;
  background: #ffffff;
  padding: 2rem;
  border-radius: 12px;
  box-shadow: 0 4px 6px -1px rgba(0, 0, 0, 0.1), 0 2px 4px -1px rgba(0, 0, 0, 0.06);
}

.header {
  margin-bottom: 1.5rem;
  text-align: center;
}

.title {
  font-size: 1.5rem;
  font-weight: bold;
  color: #111827;
}

.input-form {
  display: flex;
  gap: 0.5rem;
  margin-bottom: 1.5rem;
}

.input-field {
  flex: 1;
  padding: 0.75rem 1rem;
  border: 1px solid #d1d5db;
  border-radius: 8px;
  font-size: 1rem;
  outline: none;
  transition: border-color 0.2s;
}

.input-field:focus {
  border-color: #3b82f6;
  box-shadow: 0 0 0 2px rgba(59, 130, 246, 0.2);
}

.btn {
  padding: 0.75rem 1.25rem;
  border: none;
  border-radius: 8px;
  font-size: 1rem;
  font-weight: 500;
  cursor: pointer;
  transition: background-color 0.2s;
}

.btn-primary {
  background-color: #3b82f6;
  color: white;
}

.btn-primary:hover {
  background-color: #2563eb;
}

.todo-list {
  list-style: none;
  display: flex;
  flex-direction: column;
  gap: 0.75rem;
}

.todo-item {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 0.75rem 1rem;
  background-color: #f9fafb;
  border: 1px solid #e5e7eb;
  border-radius: 8px;
  transition: background-color 0.2s;
}

.todo-item:hover {
  background-color: #f3f4f6;
}

.todo-text {
  flex: 1;
  margin-left: 0.75rem;
  font-size: 1rem;
  color: #374151;
  word-break: break-all;
}

.todo-actions {
  display: flex;
  align-items: center;
  gap: 0.5rem;
}

.completed .todo-text {
  text-decoration: line-through;
  color: #9ca3af;
}

.delete-btn {
  background-color: transparent;
  color: #ef4444;
  border: none;
  padding: 0.5rem 0.75rem;
  border-radius: 6px;
  cursor: pointer;
  font-size: 0.875rem;
  transition: background-color 0.2s;
}

.delete-btn:hover {
  background-color: #fee2e2;
}

export interface Todo {
  id: string;
  text: string;
  completed: boolean;
}

import { useState } from 'react';
import { Todo } from './types';

export default function App() {
  const [todos, setTodos] = useState<Todo[]>([
    { id: '1', text: 'Reactのプロジェクトを作成する', completed: true },
    { id: '2', text: 'TypeScriptの型定義を行う', completed: true },
    { id: '3', text: 'やることリストアプリを完成させる', completed: false },
  ]);
  const [inputText, setInputText] = useState('');

  const handleAddTodo = (e: React.FormEvent) => {
    e.preventDefault();
    if (!inputText.trim()) return;

    const newTodo: Todo = {
      id: Date.now().toString(),
      text: inputText.trim(),
      completed: false,
    };

    setTodos([newTodo, ...todos]);
    setInputText('');
  };

  const handleToggleTodo = (id: string) => {
    setTodos(
      todos.map((todo) =>
        todo.id === id ? { ...todo, completed: !todo.completed } : todo
      )
    );
  };

  const handleDeleteTodo = (id: string) => {
    setTodos(todos.filter((todo) => todo.id !== id));
  };

  return (
    <div className="app-container">
      <header className="header">
        <h1 className="title">やることリスト</h1>
      </header>

      <form className="input-form" onSubmit={handleAddTodo}>
        <input
          type="text"
          className="input-field"
          placeholder="新しいタスクを入力..."
          value={inputText}
          onChange={(e) => setInputText(e.target.value)}
        />
        <button type="submit" className="btn btn-primary">
          追加
        </button>
      </form>

      <ul className="todo-list">
        {todos.map((todo) => (
          <li
            key={todo.id}
            className={`todo-item ${todo.completed ? 'completed' : ''}`}
          >
            <div className="todo-actions" style={{ gap: '0.75rem' }}>
              <input
                type="checkbox"
                checked={todo.completed}
                onChange={() => handleToggleTodo(todo.id)}
                style={{ width: '1.2rem', height: '1.2rem', cursor: 'pointer' }}
              />
              <span className="todo-text">{todo.text}</span>
            </div>
            <div className="todo-actions">
              <button
                type="button"
                className="delete-btn"
                onClick={() => handleDeleteTodo(todo.id)}
              >
                削除
              </button>
            </div>
          </li>
        ))}
      </ul>
    </div>
  );
}
